const MAX_SOURCES = 4; const MAX_PAGE_SIZE = 50; const MAX_PAGES = 5; const MAX_ROWS = 200;
exports.limits = { MAX_SOURCES, MAX_PAGE_SIZE, MAX_PAGES, MAX_ROWS };
exports.classifyFreshness = function (reviewDate, referenceDate) { if (!reviewDate) return 'missing review date'; const review = Date.parse(reviewDate); const reference = Date.parse(referenceDate); if (!Number.isFinite(review) || !Number.isFinite(reference)) return 'missing review date'; const days = (review - reference) / 86400000; return days < 0 ? 'stale' : days <= 30 ? 'due soon' : 'fresh'; };
function text(value) { return typeof value === 'string' ? value.trim() : ''; }
exports.parseTaxonomy = function parseTaxonomy(value) { if (Array.isArray(value)) return value.reduce((all, item) => all.concat(parseTaxonomy(item)), []); if (value && typeof value === 'object') return [text(value.Label) || text(value.Term) || text(value.Value)].filter(Boolean); return text(value).split(';').map((part) => part.replace(/^#|^\d+;#/, '').trim()).filter(Boolean); };
exports.isValidServerRelativePath = function (value) { return /^\/[\w .()'!$&+,:;=@~-]+(?:\/[\w .()'!$&+,:;=@~-]+)*\/?$/.test(value) && value.indexOf('..') < 0 && value.indexOf('\\') < 0 && !/[\u0000-\u001f\u007f?#]/.test(value) && value.indexOf('//') !== 0; };
function isValidWebUrl(value) { if (!value || /[\u0000-\u0020\u007f\\]/.test(value)) return false; try { const parsed = new URL(value); return parsed.protocol === 'https:' && !!parsed.hostname && !parsed.username && !parsed.password; } catch (_) { return false; } }
exports.safeItemUrl = function (webUrl, fileRef) { if (!isValidWebUrl(webUrl) || !exports.isValidServerRelativePath(fileRef)) return undefined; try { const parsed = new URL(webUrl); const candidate = new URL(fileRef, parsed.origin); if (candidate.protocol !== 'https:' || candidate.origin !== parsed.origin) return undefined; return candidate.href; } catch (_) { return undefined; } };
exports.safeNextUrl = function (webUrl, next) { if (!isValidWebUrl(webUrl) || typeof next !== 'string' || !next || /[\u0000-\u0020\u007f\\]/.test(next) || next.indexOf('//') === 0 || next.indexOf('..') >= 0 || /%2e/i.test(next)) return undefined; try { const base = new URL(webUrl); const parsed = new URL(next, base.origin); if (parsed.protocol !== 'https:' || parsed.origin !== base.origin || parsed.username || parsed.password) return undefined; if (parsed.pathname.indexOf('..') >= 0 || parsed.pathname.indexOf('\\') >= 0 || /[\u0000-\u001f\u007f]/.test(parsed.pathname)) return undefined; return parsed.href; } catch (_) { return undefined; } };
exports.retryAfter = function (response) { const value = response.headers && response.headers.get('Retry-After'); const seconds = value ? Number(value) : 0; return Number.isFinite(seconds) && seconds >= 0 ? Math.min(seconds * 1000, 30000) : 0; };
